"""French rules summaries of Companion qualities, supplied PDF 133–139."""

def add_qualities(rules,R):
    rows=[
    (133,'Accoutumance aux augmentations','Augmentation Acclimation','2 Karma/niveau, 10 niveaux au maximum','Réservé à Essence ≤3. Chaque niveau libère 0,1 Essence pour de nouvelles augmentations, sans augmenter l’Essence réelle.'),
    (133,'Bravade','Bravado','6 Karma','Une fois par séance, gagner 1 Atout sur une action effectuée en se donnant en spectacle ; augmenter alors le modificateur de Pression de 1.'),
    (133,'Dominateur de créatures','Critter Dominator','10 Karma','Une majeure : Influence (Intimidation) + Charisme contre Intuition + Volonté d’une créature non consciente. Contrôle pendant 1 minute par succès net, puis 1 Atout aux tests contre elle. Une seule tentative possible sur un même individu.'),
    (134,'Dresseur de créatures','Critter Trainer','10 Karma','Apprivoisement : une semaine et Influence + Charisme contre Intuition + Volonté. Chaque semaine de dressage réussie enseigne un ordre ; maximum Logique ×2 ordres. Définir un déclencheur perceptible et une action précise ; donner l’ordre coûte une mineure.'),
    (134,'Optimisation du cyberjack','Cyberjack Maximization','12 Karma','Augmenter de 1 le plus faible des deux attributs matriciels de son cyberjack.'),
    (134,'Cyborg','Cyborg','5 Karma/niveau, 10 niveaux au maximum','Nécessite Essence ≤1 et 10 niveaux d’Accoutumance aux augmentations. Libère 0,1 Essence par niveau pour de nouvelles augmentations.'),
    (134,'Contrebandier discret','Discreet Smuggler','7 Karma','Une majeure pour cacher un objet donne 1 Atout à dépenser sur ce test. Pour un objet au plus de la taille d’un pistolet lourd, le seuil de dissimulation augmente de 1 contre Perception et les senseurs.'),
    (134,'Surrégime prolongé','Extended Overdrive','6 Karma/niveau','Le surrégime d’augmentation dure un round par niveau plutôt qu’un test. Chaque test utilisant l’attribut poussé comprend un dé libre.'),
    (134,'Ambition ciblée','Focused Ambition','6 Karma','Choisir un objectif précis avec le MJ. Sur les tests poursuivant directement ce but, remplacer au choix un dé ordinaire par deux dés libres. Après réussite, choisir un nouveau but ; abandonner impose au moins un mois avant de le remplacer.'),
    (134,'Inspirer la compétence','Inspire Competence','11 Karma','Une majeure : assister un test d’équipe de n’importe quelle compétence avec Influence (Leadership) + Charisme. L’assistant ou le bénéficiaire gagne 1 Atout, au choix des joueurs.'),
    (135,'Talents multiples','Many Talents','18 Karma','À la création seulement : autorise deux attributs au maximum du métatype.'),
    (135,'Compétences multiples','Many Skills','18 Karma','À la création seulement : autorise deux compétences au rang 6.'),
    (135,'Prodige des arts martiaux','Martial Arts Prodigy','14 Karma','Apprendre un art martial ou une technique coûte 2 Karma de moins. Plusieurs apprentissages peuvent partager la même période d’entraînement.'),
    (135,'Surrégime maximal','Maximum Overdrive','7 Karma','Activer le surrégime du cyberware donne 1 Atout. En cas de complication ou d’échec critique qui le surmène, réduire la durée de perturbation de 1 round.'),
    (135,'Plus machine que métahumain','More Machine than Metahuman','5 Karma','Nécessite Essence ≤2. Les premiers soins emploient Biotech (Cybertechnologie) au lieu de Premiers soins ; le seuil devient l’Essence arrondie à l’inférieur.'),
    (136,'Muscles','Muscles','6 Karma','Dans un test social, remplacer Charisme par Force lorsque la présence physique imposante apporte réellement un avantage.'),
    (136,'Polyglotte','Polyglot','4 Karma','Nouvelle langue : 2 Karma par rang ; progression d’une langue : 1 Karma par rang. Peut atteindre le rang 4, langue maternelle.'),
    (136,'Pisteur implacable','Relentless Tracker','6 Karma','Gagner 1 Atout lors d’un test utilisant la spécialisation Pistage de Plein air.'),
    (136,'Alchimiste routinier','Rote Alchemist','10 Karma','En achetant les succès d’une préparation alchimique, obtenir 1 succès par 3 dés au lieu de 4. L’opposition, égale au Drain, achète ses succès à 1 pour 4 dés, minimum 1. Si le Drain est aussi acheté, obtenir 1 succès pour 3 dés.'),
    (136,'Optimisation logicielle','Software Optimization','10 Karma','Exécuter un programme supplémentaire sur tout appareil possédé. Gagner 1 Atout lorsqu’il est utilisé.'),
    (136,'Parasites apaisants','Soothing Static','4 Karma','Tant qu’un Bruit non totalement compensé vous affecte, les dépenses d’Atout sur les actions matricielles coûtent 1 de moins, minimum 1.'),
    (136,'Composantes de sort','Spell Components','12 Karma','Lors du lancement d’un sort, une mineure permet de dépenser des réactifs pour la résistance au Drain : +1 dé par réactif, au maximum le rang d’Enchantement (Alchimie).'),
    (136,'Esprit d’équipe','Team Player','10 Karma','Payer l’Atout d’un autre personnage au taux de 1 pour 1, seul ou en partageant le coût. La limite d’une seule dépense d’Atout sur un même test reste applicable.'),
    (136,'Rien ne colle','Teflon Coated','12 Karma','Après le jet de Pression en fin de run, imposer une relance qui ne change que votre Pression personnelle. Un seul nouveau jet commun si plusieurs runners ont ce trait.'),
    (136,'Tout pour les affaires','All Business','Bonus : 8 Karma','La Loyauté de vos contacts ne peut dépasser 3. Face à un client professionnel, gagner 1 Atout de situation aux tests d’Influence (Étiquette).'),
    (137,'Dos fragile','Bad Back','Bonus : 12 Karma','Les modificateurs de blessures vous infligent aussi l’état Estropié ; il disparaît avec ces modificateurs.'),
    (137,'Temps emprunté','Borrowed Time','Bonus : 25 Karma','Au début de chaque séance, après rafraîchissement de l’Atout, tester le plus élevé de Constitution ou Volonté + Atout. Seuil initial 1, puis +1 par séance. Un échec annonce la mort pendant la séance, sauf point d’Atout cramé ; racheter le trait est nécessaire pour supprimer la menace.'),
    (137,'Prime sur la tête','Bounty','Bonus : 10 Karma','À Pression personnelle 17 ou plus, la traque des chasseurs de primes impose de commencer chaque séance avec zéro point dans la réserve d’Atout.'),
    (137,'Douleur chronique','Chronic Pain','Bonus : 15 Karma','Début de séance : Constitution + Volonté, seuil 3 + nombre de séances sans crise. Échec : −1 dé à tous les tests sauf encaissement pendant toute la séance. Les effets réduisant les malus de blessures n’annulent pas cette douleur.'),
    (137,'Accro au combat','Combat Junkie','Bonus : 6 Karma','Les provocations bénéficient de 1 Atout adverse. Pas d’Atout pour Jauger les intentions hors combat. Fuir avec moins de 6 cases de dommages interdit gain et dépense d’Atout jusqu’au prochain combat ou à la séance suivante.'),
    (137,'Cyberpsychose','Cyber Psychosis','Bonus : 8 Karma/niveau, 3 niveaux au maximum','Nécessite Essence ≤1. Lorsque la réserve d’Atout tombe à zéro, perdre une action mineure par round et par niveau jusqu’au retour d’au moins un point d’Atout.'),
    (138,'Délicatesse','Finesse','Bonus : 7 Karma','Aucun gain ni dépense d’Atout sur une action qui produirait un modificateur de Pression. Si vous n’en produisez personnellement aucun, réduire celui de l’équipe de 1.'),
    (138,'Syndrome d’acquisition de matériel','Gear Acquisition Syndrome','Bonus : 5 Karma/niveau, 3 niveaux au maximum','Nécessite une spécialisation ou maîtrise. Acheter chaque mois au moins 1 000 ¥ de matériel par niveau ; sinon, perdre les bonus de toutes les spécialisations et maîtrises jusqu’à satisfaction de ce besoin. La dette mensuelle ne s’accumule pas.'),
    (138,'Sujet aux complications','Glitchy','Bonus : 12 Karma','Toute complication devient un échec critique sans aucun succès, quel que soit le nombre de succès obtenu au jet.'),
    (138,'Gourmand','Gourmand','Bonus : 5 Karma','Manger en dessous du standard de vie Élevé, notamment un plat à moins de 20 ¥, inflige Nauséeux pendant une heure.'),
    (138,'Robin des Ombres','Hooder','Bonus : 5 Karma/niveau, 3 niveaux au maximum','Donner au moins 1 000 ¥ par niveau chaque mois, hors équipe et famille. Sinon, l’adversaire gagne 1 Atout de situation à tout test opposé contre vous. La somme impayée ne dépasse pas un mois.'),
    (138,'Traqué','Hunted','Bonus : 5 Karma/niveau, 5 niveaux au maximum','À Pression personnelle 15 ou plus, résister avec Constitution à VD 7P +1 par niveau au début de chaque séance après récupération de l’Atout. Les soins immédiats sont permis, mais pas la récupération à long terme avant le début de jeu.'),
    (138,'Indécis','Indecisive','Bonus : 11 Karma','Nécessite quatre actions mineures par round. Impossible de convertir les mineures en majeure tant que la réserve d’Atout n’atteint pas 5.'),
    (138,'Sujet aux blessures','Injury Prone','Bonus : 15 Karma','Chaque source de dommages inflige une case supplémentaire du même type, P ou E.'),
    (138,'Tueur','Killer','Bonus : 4 Karma','Impossible de gagner ou dépenser de l’Atout pour une attaque ou un sort infligeant des dommages étourdissants.'),
    (139,'Attributs limités','Limited Attributes','Bonus : 5 Karma','À la création seulement : aucun attribut ne peut être au maximum du métatype. Avec les parcours de vie, transférer le point excédentaire vers un autre attribut.'),
    (139,'Compétences limitées','Limited Skills','Bonus : 5 Karma','À la création seulement : aucune compétence au maximum initial. Avec les parcours de vie, transférer le rang excédentaire à une autre compétence.'),
    (139,'Malchance spectaculaire','Momentous Misfortune','Bonus : 25 Karma','Le personnage ne peut gagner qu’un seul point d’Atout par round.'),
    (139,'Non létal','Non-Lethal','Bonus : 5 Karma','Impossible de gagner ou dépenser de l’Atout pour une attaque ou un sort infligeant des dommages physiques.'),
    (139,'Allergie aux stimpatchs','Stim Patch Allergy','Bonus : 10 Karma','Un stimpatch impose aussi Désorienté jusqu’à la fin de son effet.'),
    (139,'Sensibilité à une toxine, à préciser','Toxin Susceptibility (specify toxin)','Bonus : 2 Karma','Choisir une toxine. Sa Virulence est augmentée de 2 contre vous et l’Atout est interdit aux tests pour y résister.'),
    (139,'Difficulté à faire confiance','Trust Issues','Bonus : 10 Karma','Aucun gain ni dépense d’Atout pour Influence (Étiquette ou Négociation) ou Jauger les intentions. Loyauté maximale 3 pour les contacts et au sein d’un groupe magique.'),
    (139,'Nerveux','Twitchy','Bonus : 5 Karma','Appliquer −1 dé aux tests de Sang-froid pour chaque dé d’initiative que le personnage peut lancer.'),
    ]
    for page,title,en,cost,effect in rows:
        R('companion',page,'Trait : '+title,effect,topic='personnage',original=en,fields=[{'label':'Coût ou bonus en Karma','value':cost}],tags=('trait',title,en))
        rules[-1]['practical']=True
        rules[-1]['procedure']={'effect':effect,'cost':cost}
